function visualEvidenceFile(file,work,jsonOnly=false){
 const real=fs.realpathSync(file),base=fs.realpathSync(BASE),own=fs.realpathSync(work);
 if(!(real.startsWith(base+'/')||!jsonOnly&&(real.startsWith(own+'/thumbnails/')||real===own+'/thumbnail.jpg')))fail('Visual evidence path resolves outside approved scratch/current thumbnails');
 const st=fs.statSync(real);if(!st.isFile()||st.size<=0||st.size>(jsonOnly?1024*1024:32*1024*1024))fail('Invalid visual evidence file size/type');return real;
}
